// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 amt) public {
        amt = bound(amt, 0, 1 ether);
        vm.assume(caller != address(this));

        vm.deal(address(c), 1 ether);

        Reverter rev = new Reverter();

        vm.deal(caller, amt);
        vm.prank(caller);
        bool ok;
        try c.sendMoney(address(rev), amt) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("nope");
    }
    receive() external payable {
        revert("nope");
    }
}
